// uninstallSummary is what runUninstall found to remove, carried to the
// confirmation prompt so the user approves exactly the scope that was detected.
type uninstallSummary struct {
	entireDirExists   bool
	gitHooksInstalled bool
	sessionStateCount int
	shadowBranchCount int
	hookState         agentHookState
}

// confirmUninstall prints the removal summary and asks the user to confirm.
// It returns false when the user declined, and an error when the confirmation
// could not be asked at all.
func confirmUninstall(w, errW io.Writer, summary uninstallSummary) (bool, error) {
	fmt.Fprintln(w, "\nThis will completely remove Entire from this repository:")
	if summary.entireDirExists {
		fmt.Fprintln(w, "  - .entire/ directory")
	}
	if summary.gitHooksInstalled {
		fmt.Fprintln(w, "  - Git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
	}
	if summary.sessionStateCount > 0 {
		fmt.Fprintf(w, "  - Session state files (%d)\n", summary.sessionStateCount)
	}
	if summary.shadowBranchCount > 0 {
		fmt.Fprintf(w, "  - Shadow branches (%d)\n", summary.shadowBranchCount)
	}
	if len(summary.hookState.installed) > 0 {
		fmt.Fprintf(w, "  - Agent hooks (%s)\n", strings.Join(agentDisplayNames(summary.hookState.installed), ", "))
	}
	// Its own line, not folded into the one above: that line asserts hooks are
	// installed, which for these plugins is exactly what we could not find out.
	if len(summary.hookState.unchecked) > 0 {
		fmt.Fprintf(w, "  - Agent hooks that could not be checked (%s)\n", strings.Join(agentDisplayNames(summary.hookState.uncheckedNames()), ", "))
	}
	fmt.Fprintln(w)

	// Without this guard the confirm below reaches huh, whose bubbletea
	// program opens /dev/tty directly. A caller with no terminal gets a
	// bubbletea internal error instead of the flag that unblocks them, and a
	// `go test` run that happens to have a controlling terminal blocks on a
	// rendered prompt.
	if !interactive.CanPromptInteractively() {
		fmt.Fprintln(errW, "No terminal available to confirm the uninstall. Re-run with --force to uninstall non-interactively.")
		return false, NewSilentError(errors.New("uninstall confirmation requires a terminal"))
	}

	var confirmed bool
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title("Are you sure you want to uninstall Entire?").
				Affirmative("Yes, uninstall").
				Negative("Cancel").
				Value(&confirmed),
		),
	)

	if err := form.Run(); err != nil {
		return false, fmt.Errorf("confirmation cancelled: %w", err)
	}
	return confirmed, nil
}

// countSessionStates returns the number of active session state files.
func countSessionStates(ctx context.Context) int {
	store, err := session.NewStateStore(ctx)
	if err != nil {
		return 0
	}
	states, err := store.List(ctx)
	if err != nil {
		return 0
	}
	return len(states)
}

// countShadowBranches returns the number of shadow branches.
func countShadowBranches(ctx context.Context) int {
	branches, err := strategy.ListShadowBranches(ctx)
	if err != nil {
		return 0
	}
	return len(branches)
}

// checkEntireDirExists checks if the .entire directory exists.
func checkEntireDirExists(ctx context.Context) bool {
	entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
	if err != nil {
		entireDirAbs = paths.EntireDir
	}
	_, err = os.Lstat(entireDirAbs)
	return err == nil
}

// pluginUninstallCommand returns the command line a user can run by hand to
// remove an external plugin's hooks.
//
// The protocol promises every subcommand ENTIRE_REPO_ROOT,
// ENTIRE_PROTOCOL_VERSION and a repo-root working directory
// (docs/architecture/external-agent-protocol.md), so a plugin is entitled to
// rely on them. Printing the bare binary hands the user a command a conforming
// plugin can reject.
func pluginUninstallCommand(repoRoot string, name types.AgentName) string {
	return pluginUninstallCommandFor(runtime.GOOS, repoRoot, name)
}

// pluginUninstallCommandFor is pluginUninstallCommand with the OS injected, so
// tests can pin both shapes from any platform.
//
// The line must be pasteable into the shell the user actually has: the POSIX
// `cd x && VAR=y bin` form is a syntax error in PowerShell and sets no
// environment in cmd.exe, so on Windows it would hand the user a recovery
// command that cannot run — and this command is printed precisely when it is
// the user's last chance to act. PowerShell is the shape to print there: it is
// the default shell on modern Windows, and a cmd.exe user can still read the
// intent off it, while the reverse (cmd.exe's `set VAR=y & bin`) leaks trailing
// spaces into values and is wrong in PowerShell too.
func pluginUninstallCommandFor(goos, repoRoot string, name types.AgentName) string {
	if goos == "windows" {
		root := powerShellQuote(repoRoot)
		return fmt.Sprintf("cd %s; $env:ENTIRE_REPO_ROOT = %s; $env:ENTIRE_PROTOCOL_VERSION = '%d'; entire-agent-%s uninstall-hooks",
			root, root, external.ProtocolVersion, name)
	}
	// Quoted because this is a line the user pastes into a shell, and a repo path
	// with a space in it is ordinary: unquoted, `cd /My Repo && ...` runs cd
	// against the wrong argument and the command silently does nothing useful.
	root := shellQuote(repoRoot)
	return fmt.Sprintf("cd %s && ENTIRE_REPO_ROOT=%s ENTIRE_PROTOCOL_VERSION=%d entire-agent-%s uninstall-hooks",
		root, root, external.ProtocolVersion, name)
}

// powerShellQuote wraps a string in PowerShell single quotes, where the only
// escape is doubling an embedded single quote. Single quotes, not double:
// PowerShell expands $ and ` inside double quotes, and a path is data.
func powerShellQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

// uninstallAgentHooks removes hooks from the agents hookState reported as
// installed, and reports the unchecked ones. The sweep is reused rather than
// re-detected: for an external agent AreHooksInstalled is a subprocess, and it
// is also what the confirmation summary was built from, so this uninstalls
// exactly what the user was shown. An agent that cleanly reported no hooks is
// in neither set and is left alone.
//
// It prints its own report as it goes — removals to w, warnings to errW — and
// owns its own success verdict: a built-in problem (failed removal or
// uncheckable config, always Entire's own bug to surface) fails the step, an
// external plugin problem does so only under strict, since it is third-party
// code Entire cannot fix — its warning, with the plugin command the user can
// run by hand, is the whole report. A re-run can also retry the plugin
// (uninstall discovery is ungated), but the plugin binary itself may be what
// is broken, and invoking it directly shows its output.
func uninstallAgentHooks(ctx context.Context, w, errW io.Writer, repoRoot string, hookState agentHookState, strict bool) bool {
	if len(hookState.installed) == 0 && len(hookState.unchecked) == 0 {
		fmt.Fprintln(w, "  No agent hooks to remove")
		return true
	}

	builtinProblem := false
	externalProblem := false
	for _, name := range hookState.installed {
		ag, err := agent.Get(name)
		if err != nil {
			continue
		}
		hs, ok := agent.AsHookSupport(ag)
		if !ok {
			continue
		}

		switch err := hs.UninstallHooks(ctx); {
		case err != nil && external.IsExternal(ag):
			externalProblem = true
			fmt.Fprintf(errW, "Warning: failed to remove agent hooks: %s (external): %v\n", agentDisplayName(name), err)
			fmt.Fprintf(errW, "  %s hooks are still installed. Remove them with:\n    %s\n", agentDisplayName(name), pluginUninstallCommand(repoRoot, name))
		case err != nil:
			builtinProblem = true
			fmt.Fprintf(errW, "Warning: failed to remove agent hooks: %s: %v\n", agentDisplayName(name), err)
		default:
			fmt.Fprintf(w, "  Removed %s hooks\n", ag.Type())
		}
	}

	for _, u := range hookState.unchecked {
		if u.external {
			// "may": we never found out whether this plugin has hooks, and we did
			// not ask it to remove them — asking a plugin that cannot answer to
			// mutate state is not something to do on the user's behalf.
			externalProblem = true
			fmt.Fprintf(errW, "Warning: could not check whether %s hooks are installed: %v\n", agentDisplayName(u.name), u.err)
			fmt.Fprintf(errW, "  %s hooks may still be installed. Remove them with:\n    %s\n", agentDisplayName(u.name), pluginUninstallCommand(repoRoot, u.name))
		} else {
			builtinProblem = true
			fmt.Fprintf(errW, "Warning: could not check whether %s hooks are installed - they may or may not remain: %v\n", agentDisplayName(u.name), u.err)
		}
	}

	return !builtinProblem && (!strict || !externalProblem)
}

// removeAllSessionStates removes all session state files and the directory.
func removeAllSessionStates(ctx context.Context) (int, error) {
	store, err := session.NewStateStore(ctx)
	if err != nil {
		return 0, fmt.Errorf("failed to create state store: %w", err)
	}

	// Count states before removing
	states, err := store.List(ctx)
	if err != nil {
		return 0, fmt.Errorf("failed to list session states: %w", err)
	}
	count := len(states)

	// Remove the entire directory
	if err := store.RemoveAll(); err != nil {
		return 0, fmt.Errorf("failed to remove session states: %w", err)
	}

	// Sweep the per-session advisory lock files. These live alongside the
	// state directory rather than inside it (see strategy.stateLockPath) so
	// session-listing code doesn't have to filter them out. Best-effort:
	// failing here doesn't undo the state-file removal.
	if commonDir, cdErr := strategy.GetGitCommonDir(ctx); cdErr == nil {
		_ = os.RemoveAll(filepath.Join(commonDir, "entire-session-locks"))
	}

	return count, nil
}

// removeEntireDirectory removes the .entire directory.
func removeEntireDirectory(ctx context.Context) error {
	entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
	if err != nil {
		entireDirAbs = paths.EntireDir
	}
	if err := os.RemoveAll(entireDirAbs); err != nil {
		return fmt.Errorf("failed to remove .entire directory: %w", err)
	}
	return nil
}

// removeAllShadowBranches removes all shadow branches.
func removeAllShadowBranches(ctx context.Context) (int, error) {
	branches, err := strategy.ListShadowBranches(ctx)
	if err != nil {
		return 0, fmt.Errorf("failed to list shadow branches: %w", err)
	}
	if len(branches) == 0 {
		return 0, nil
	}
	deleted, _, err := strategy.DeleteShadowBranches(ctx, branches)
	return len(deleted), err
}

package cli

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
	"time"

	"charm.land/lipgloss/v2"
	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/cmd/entire/cli/palette"

	"golang.org/x/term"
)

// statusStyles holds pre-built lipgloss styles and terminal metadata.
type statusStyles struct {
	colorEnabled bool
	width        int

	// Styles
	green   lipgloss.Style
	red     lipgloss.Style
	gray    lipgloss.Style
	bold    lipgloss.Style
	dim     lipgloss.Style
	agent   lipgloss.Style // accent (magenta) for agent names
	cyan    lipgloss.Style
	yellow  lipgloss.Style // yellow for stale warnings
	magenta lipgloss.Style
}

// newStatusStyles creates styles appropriate for the output writer.
func newStatusStyles(w io.Writer) statusStyles {
	useColor := shouldUseColor(w)
	width := getTerminalWidth(w)

	s := statusStyles{
		colorEnabled: useColor,
		width:        width,
	}

	if useColor {
		s.green = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Success))
		s.red = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Error))
		s.gray = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Muted))
		s.bold = lipgloss.NewStyle().Bold(true)
		s.dim = lipgloss.NewStyle().Faint(true)
		s.agent = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color(palette.Accent))
		s.cyan = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Info))
		s.yellow = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Warning))
		s.magenta = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Magenta))
	}

	return s
}

// render applies a style to text only when color is enabled.
func (s statusStyles) render(style lipgloss.Style, text string) string {
	if !s.colorEnabled {
		return text
	}
	return style.Render(text)
}

// shouldUseColor returns true if the writer supports color output.
func shouldUseColor(w io.Writer) bool {
	return interactive.ShouldStyle(w)
}

// getTerminalWidth returns the terminal width, capped at 80 with a fallback of 60.
// It first checks the writer itself, then falls back to Stdout/Stderr.
func getTerminalWidth(w io.Writer) int {
	// Try the output writer first
	if f, ok := w.(*os.File); ok {
		if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
			return min(width, 80)
		}
	}

	// Fall back to Stdout, then Stderr
	for _, f := range []*os.File{os.Stdout, os.Stderr} {
		if f == nil {
			continue
		}
		if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
			return min(width, 80)
		}
	}

	return 60
}

// formatTokenCount formats a token count for display.
// 0 → "0", 500 → "500", 1200 → "1.2k", 14300 → "14.3k"
func formatTokenCount(n int) string {
	if n < 1000 {
		return strconv.Itoa(n)
	}
	f := float64(n) / 1000.0
	s := fmt.Sprintf("%.1f", f)
	// Remove trailing ".0" for clean display (e.g., 1000 → "1k" not "1.0k")
	s = strings.TrimSuffix(s, ".0")
	return s + "k"
}

// totalTokens recursively sums all token fields including subagent tokens.
func totalTokens(tu *agent.TokenUsage) int {
	if tu == nil {
		return 0
	}
	total := saturatingIntAdd(tu.InputTokens, tu.CacheCreationTokens)
	total = saturatingIntAdd(total, tu.CacheReadTokens)
	total = saturatingIntAdd(total, tu.OutputTokens)
	total = saturatingIntAdd(total, totalTokens(tu.SubagentTokens))
	return total
}

// explainRow is one entry in a metadata block: dim label + plain value.
type explainRow struct {
	Label string
	Value string
}

// identityBullet renders "● <label> <id>\n". Bullet is the brand accent
// (magenta) when color is enabled; ID is also the accent to mirror the existing
// checkpoint header. When
// id is empty (e.g., temporary checkpoints append "[temporary]" to the label
// instead of using an id slot), the trailing space + id is suppressed.
func (s statusStyles) identityBullet(label, id string) string {
	if id == "" {
		if !s.colorEnabled {
			return fmt.Sprintf("● %s\n", label)
		}
		bullet := s.render(lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Accent)), "●")
		return fmt.Sprintf("%s %s\n", bullet, s.render(s.bold, label))
	}
	if !s.colorEnabled {
		return fmt.Sprintf("● %s %s\n", label, id)
	}
	bullet := s.render(lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Accent)), "●")
	idStyled := s.render(lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Accent)), id)
	return fmt.Sprintf("%s %s %s\n", bullet, s.render(s.bold, label), idStyled)
}

// listIdentityBullet renders "● <id>  <suffix>\n" — accent bullet, bold-accent ID,
// then plain (or dimmed) suffix. Used by the explain list view where the ID is
// the primary identifier (different ordering from identityBullet, which puts
// the static label first).
func (s statusStyles) listIdentityBullet(id, suffix string) string {
	if !s.colorEnabled {
		if suffix == "" {
			return fmt.Sprintf("● %s\n", id)
		}
		return fmt.Sprintf("● %s  %s\n", id, suffix)
	}
	bullet := s.render(lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Accent)), "●")
	idStyled := s.render(lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Accent)).Bold(true), id)
	if suffix == "" {
		return fmt.Sprintf("%s %s\n", bullet, idStyled)
	}
	return fmt.Sprintf("%s %s  %s\n", bullet, idStyled, suffix)
}

// successBullet renders "✓ <label>\n" — green checkmark + bold label.
func (s statusStyles) successBullet(label string) string {
	if !s.colorEnabled {
		return fmt.Sprintf("✓ %s\n", label)
	}
	return fmt.Sprintf("%s %s\n", s.render(s.green, "✓"), s.render(s.bold, label))
}

// failureBullet renders "✗ <label>\n" — red ✗ + bold label.
func (s statusStyles) failureBullet(label string) string {
	if !s.colorEnabled {
		return fmt.Sprintf("✗ %s\n", label)
	}
	return fmt.Sprintf("%s %s\n", s.render(s.red, "✗"), s.render(s.bold, label))
}

// renderIdentity returns identityBullet + metadataRows + horizontalRule + trailing newline.
// This is the exact shape used by formatCheckpointHeader; rendering an entire
// header block is one call instead of three.
func (s statusStyles) renderIdentity(label, id string, rows []explainRow) string {
	var b strings.Builder
	b.WriteString(s.identityBullet(label, id))
	b.WriteString(s.metadataRows(rows))
	b.WriteString(s.horizontalRule(s.width))
	b.WriteString("\n")
	return b.String()
}

// renderSuccess returns successBullet + metadataRows. No trailing rule (success
// blocks are short and don't precede a body section).
func (s statusStyles) renderSuccess(label string, rows []explainRow) string {
	if len(rows) == 0 {
		return s.successBullet(label)
	}
	return s.successBullet(label) + s.metadataRows(rows)
}

// renderFailure returns failureBullet + metadataRows. Used when a command
// prints a styled error block to errW before returning *SilentError.
func (s statusStyles) renderFailure(label string, rows []explainRow) string {
	if len(rows) == 0 {
		return s.failureBullet(label)
	}
	return s.failureBullet(label) + s.metadataRows(rows)
}

// metadataRows joins rows with consistent label-column width:
// max(7, widest label in slice). 7-char-pad + 2-space-gutter is visually
// equivalent to the existing formatCheckpointHeader's %-9s + no-gutter
// (see explain.go) for any label up to 9 chars, and the explicit gutter
// scales cleanly when a longer label (e.g. "checkpoints", 11 chars) is
// present.
func (s statusStyles) metadataRows(rows []explainRow) string {
	width := 7
	for _, r := range rows {
		if l := len(r.Label); l > width {
			width = l
		}
	}
	return s.metadataRowsWithWidth(rows, width)
}

// metadataRowsWithWidth is the underlying renderer used by
// metadataRows. The caller computes the column width; this function owns the
// byte layout (2-space indent, padded label, 2-space gutter, value, newline)
// and the empty-label continuation branch (4-space hanging indent, no dim
// styling — used for multi-line items beneath a parent label like "causes").
//
// The min=7 default chosen by metadataRows produces output
// identical to formatCheckpointHeader's %-9s + no-gutter rendering at
// explain.go for any label up to 9 chars.
func (s statusStyles) metadataRowsWithWidth(rows []explainRow, width int) string {
	var b strings.Builder
	for _, r := range rows {
		// Empty-label rows are continuation lines (e.g., bullet items under a "causes" row).
		// They render with a 4-space hanging indent and no dim styling.
		if r.Label == "" {
			fmt.Fprintf(&b, "    %s\n", r.Value)
			continue
		}
		paddedLabel := fmt.Sprintf("%-*s", width, r.Label)
		if s.colorEnabled {
			paddedLabel = s.render(s.dim, paddedLabel)
		}
		// Two-space indent + padded label + two-space gutter + value + newline.
		fmt.Fprintf(&b, "  %s  %s\n", paddedLabel, r.Value)
	}
	return b.String()
}

// horizontalRule renders a dimmed horizontal rule of the given width.
func (s statusStyles) horizontalRule(width int) string {
	rule := strings.Repeat("─", width)
	return s.render(s.dim, rule)
}

// sectionRule renders a section header like: ── Active Sessions ────────────
func (s statusStyles) sectionRule(label string, width int) string {
	prefix := "── "
	content := label + " "
	usedWidth := len([]rune(prefix)) + len([]rune(content))
	trailing := width - usedWidth
	if trailing < 1 {
		trailing = 1
	}

	var b strings.Builder
	b.WriteString(s.render(s.dim, "── "))
	b.WriteString(s.render(s.dim, label))
	b.WriteString(" ")
	b.WriteString(s.render(s.dim, strings.Repeat("─", trailing)))
	return b.String()
}

// activeTimeDisplay formats a last interaction time for display.
// Returns "active now" for recent activity (<1min), otherwise "active Xm ago".
func activeTimeDisplay(lastInteraction *time.Time) string {
	if lastInteraction == nil {
		return ""
	}
	d := time.Since(*lastInteraction)
	if d < time.Minute {
		return "active now"
	}
	return "active " + timeAgo(*lastInteraction)
}

